import {categories,euro,dateKey,shiftDate,validateImport,demoData,pack,extent} from './core.js';
const $=id=>document.getElementById(id),today=dateKey(),key='bulles-transactions-v1',reflectionKey='bulles-reflections-v1';let selected=today,items=demoData(today),isDemo=true,notes={},selectedId=null,tab='daily';
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4000)}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Stockage indisponible : ces données ne seront pas conservées après fermeture.');return false}}
try{const stored=localStorage.getItem(key);if(stored){items=validateImport(JSON.parse(stored));isDemo=false}const saved=JSON.parse(localStorage.getItem(reflectionKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))notes=saved}catch{toast('Les données locales étaient illisibles. La démonstration est affichée.')}
const byDate=day=>items.filter(t=>t.date===day),sum=list=>list.reduce((a,t)=>a+t.amountCents,0),fmt=day=>new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Paris'}).format(new Date(day+'T12:00:00Z'));
function node(tag,text,cls){const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e}
function svgNode(tag,attrs){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);return e}
function draw(svg,list,view,interactive=true){svg.replaceChildren();svg.setAttribute('viewBox',view);for(const p of pack(list)){const cat=categories[p.category],g=svgNode('g',{class:'bubble',transform:`translate(${p.x},${p.y})`});g.append(svgNode('circle',{r:p.r,fill:cat.color}));if(interactive){g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',`${p.merchant}, ${euro(p.amountCents)}. Ouvrir le détail`);g.addEventListener('click',()=>openDetail(p));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail(p)}});const size=Math.min(17,Math.max(9,p.r*.27));if(p.r>12){const icon=svgNode('text',{y:-p.r*.26,'font-size':Math.min(29,p.r*.52)});icon.textContent=cat.emoji;g.append(icon);const amount=svgNode('text',{y:p.r*.18,'font-size':size,'font-weight':600});amount.textContent=euro(p.amountCents);g.append(amount);if(p.r>24){const name=svgNode('text',{y:p.r*.51,'font-size':Math.min(10,p.r*.17)});name.textContent=p.merchant.length>16?p.merchant.slice(0,14)+'…':p.merchant;g.append(name)}}}svg.append(g)}}
function render(){const list=byDate(selected),days=Array.from({length:7},(_,i)=>shiftDate(selected,i-6)),week=items.filter(t=>days.includes(t.date));const grouped=Object.values(Object.groupBy?Object.groupBy(items,t=>t.date):items.reduce((m,t)=>{(m[t.date]??=[]).push(t);return m},{}));const view=extent(grouped.map(pack));$('day').value=selected;$('dayName').textContent=selected===today?"Aujourd'hui":new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',timeZone:'Europe/Paris'}).format(new Date(selected+'T12:00:00Z'));$('dateCaption').textContent=fmt(selected);$('total').textContent=euro(sum(list));$('count').textContent=`${list.length} achat${list.length===1?'':'s'}${list.some(t=>t.status==='pending')?' · opérations en attente incluses':''}`;$('average').textContent=euro(Math.round(sum(week)/7));$('empty').hidden=list.length>0;draw($('cluster'),list,view);$('insight').textContent=list.length?`${list.filter(t=>t.amountCents<=1000).length} petit(s) achat(s) de 10 € ou moins, pour ${euro(sum(list.filter(t=>t.amountCents<=1000)))} au total.`:'Une journée à compléter quand les données seront disponibles.';$('legend').replaceChildren();for(const [id,c]of Object.entries(categories)){const amount=sum(list.filter(t=>t.category===id));if(!amount)continue;const row=node('div',null,'legend-row'),dot=node('i');dot.style.background=c.color;row.append(dot,node('span',c.name),node('strong',euro(amount)));$('legend').append(row)}$('transactions').replaceChildren();for(const t of list){const b=node('button',null,'transaction');const label=node('span',t.merchant);label.append(node('small',`${categories[t.category].name} · ${t.status==='pending'?'En attente':'Comptabilisé'}`));b.append(node('span',categories[t.category].emoji,'emoji'),label,node('strong',euro(t.amountCents)));b.onclick=()=>openDetail(t);$('transactions').append(b)}$('demoBanner').hidden=!isDemo;$('source').textContent=isDemo?'○ Démonstration':'○ Données importées';$('freshness').textContent=isDemo?'Données fictives · aucune synchronisation bancaire':'Import local · aucune synchronisation bancaire';$('weekCards').replaceChildren();for(const d of days){const b=node('button',null,'week-card');b.append(node('span',new Intl.DateTimeFormat('fr-FR',{weekday:'short',day:'numeric',timeZone:'Europe/Paris'}).format(new Date(d+'T12:00:00Z'))));const svg=svgNode('svg',{'aria-hidden':'true'});draw(svg,byDate(d),view,false);b.append(svg,node('strong',euro(sum(byDate(d)))));b.onclick=()=>{selected=d;switchTab('daily');render()};$('weekCards').append(b)}$('weekTotal').textContent=euro(sum(week));const small=week.filter(t=>t.amountCents<=1000);$('smallTotal').textContent=euro(sum(small));$('weekInsight').textContent=`${small.length} petit(s) achat(s) sur ${week.length} achat(s) enregistrés. Les journées vides sont incluses dans la moyenne. ${isDemo?'Ce sont des exemples fictifs.':'Ces totaux décrivent uniquement les données importées.'}`}
function switchTab(value){tab=value;$('daily').hidden=value!=='daily';$('weekly').hidden=value!=='weekly';$('dailyNav').classList.toggle('active',value==='daily');$('weekNav').classList.toggle('active',value==='weekly')}
function openDetail(t){selectedId=t.id;$('detailCategory').textContent=categories[t.category].name;$('detailName').textContent=t.merchant;$('detailAmount').textContent=euro(t.amountCents);$('detailMeta').textContent=`${fmt(t.date)} · ${t.status==='pending'?'En attente':'Comptabilisé'} · ${t.dateBasis==='transaction'?"Date d'achat fournie":"Date comptable, date d'achat non fournie"}${isDemo?' · Exemple fictif':''}`;const n=notes[t.id]||{};$('note').value=typeof n.note==='string'?n.note:'';for(const b of $('feelings').children)b.classList.toggle('chosen',n.feeling===b.dataset.feeling);$('detail').showModal()}
$('note').addEventListener('input',()=>{if(!selectedId)return;notes[selectedId]={...(notes[selectedId]||{}),note:$('note').value};persist(reflectionKey,notes)});for(const b of $('feelings').children)b.onclick=()=>{if(!selectedId)return;notes[selectedId]={...(notes[selectedId]||{}),feeling:b.dataset.feeling};persist(reflectionKey,notes);for(const btn of $('feelings').children)btn.classList.toggle('chosen',btn===b)};
$('prev').onclick=()=>{selected=shiftDate(selected,-1);render()};$('next').onclick=()=>{selected=shiftDate(selected,1);render()};$('today').onclick=()=>{selected=today;render()};$('day').onchange=()=>{if($('day').value){selected=$('day').value;render()}};$('listToggle').onclick=()=>{$('transactions').hidden=!$('transactions').hidden;$('listToggle').textContent=$('transactions').hidden?'↓ Voir les achats en liste':'↑ Masquer la liste'};$('dailyNav').onclick=()=>switchTab('daily');$('weekNav').onclick=()=>switchTab('weekly');$('bankNav').onclick=$('source').onclick=()=>$('bank').showModal();
$('import').onchange=async()=>{const file=$('import').files[0];if(!file)return;try{if(file.size>3000000)throw Error('Fichier trop grand (3 Mo maximum).');const imported=validateImport(JSON.parse(await file.text()));if(!persist(key,{version:1,transactions:imported})){throw Error('Import non enregistré : active le stockage du navigateur.')}items=imported;notes={};persist(reflectionKey,notes);isDemo=false;selected=items.length?items.map(t=>t.date).sort().at(-1):today;render();$('importStatus').textContent=`${items.length} achat(s) importé(s). Les données fictives ont été remplacées.`;toast('Tes données sont maintenant affichées.')}catch(e){$('importStatus').textContent=e instanceof SyntaxError?'JSON invalide. Vérifie le format du fichier.':e.message}$('import').value=''};
$('reset').onclick=()=>{try{localStorage.removeItem(key);localStorage.removeItem(reflectionKey)}catch{toast('Impossible d’effacer le stockage local.');return}items=demoData(today);isDemo=true;notes={};selected=today;render();$('importStatus').textContent='Données locales effacées. Démonstration rétablie.'};
for(const dialog of [$('bank'),$('detail')])dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true}};
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(reg=>{const offer=()=>{if(reg.waiting){$('update').hidden=false;$('update').onclick=()=>reg.waiting.postMessage({type:'SKIP_WAITING'})}};offer();reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)offer()})});window.addEventListener('focus',()=>reg.update().catch(()=>{}));let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing&&navigator.serviceWorker.controller){refreshing=true;location.reload()}})}).catch(()=>{})}render();
